#!/usr/bin/env node
// Builds de.html and ko.html from index.html.
//
// The homepage switches language in the browser, so search engines only ever
// saw one URL. Each generated page is a copy of index.html that already
// carries its language in the static HTML: <html lang>, <title>, description,
// Open Graph tags, canonical URL and the [data-lang-key] text. The pages sit
// next to index.html so every relative asset path keeps working unchanged.
//
// index.html stays the only file to edit; these copies are regenerated by
// .github/workflows/homepage-tailwind.yml and build-research-index.yml.
//
//   node tools/build_language_pages.cjs          write de.html and ko.html
//   node tools/build_language_pages.cjs --check  exit 1 when either is stale
'use strict';

const fs = require('fs');
const path = require('path');
const vm = require('vm');
const { loadTranslations, prefill } = require('./prefill_lang_keys.cjs');

const ROOT = path.join(__dirname, '..');
const SITE = 'https://raven-deadwire.github.io/RavenForge-Luthier-Intelligence/';
const PAGES = {
  de: { file: 'de.html', locale: 'de_DE' },
  ko: { file: 'ko.html', locale: 'ko_KR' },
};
const LOCALES = { en: 'en_US', de: 'de_DE', ko: 'ko_KR' };

const escapeAttr = value => String(value).replace(/&/g, '&amp;').replace(/"/g, '&quot;').replace(/</g, '&lt;');
const escapeText = value => String(value).replace(/&/g, '&amp;').replace(/</g, '&lt;');

// Page titles and subtitles shown to visitors come from assets/site-context.js.
function loadSiteCopy() {
  const text = fs.readFileSync(path.join(ROOT, 'assets', 'site-context.js'), 'utf8');
  const start = text.indexOf('const copy = {');
  const end = text.indexOf('\n  };', start);
  if (start < 0 || end < 0) throw new Error('copy object not found in assets/site-context.js');
  return vm.runInNewContext(`(${text.slice(start + 'const copy = '.length, end + '\n  }'.length)})`);
}

function replaceOnce(text, pattern, replacement, label) {
  let count = 0;
  const out = text.replace(pattern, (...args) => { count += 1; return typeof replacement === 'function' ? replacement(...args) : replacement; });
  if (count !== 1) throw new Error(`${label}: expected one match in index.html, found ${count}`);
  return out;
}

function build(source, lang, translations, siteCopy) {
  const { file, locale } = PAGES[lang];
  const copy = siteCopy[lang];
  const url = SITE + file;
  const description = `RavenForge Luthier Intelligence — ${copy.headerSubtitle}. ${copy.heroDescription}`;
  let html = source;

  html = replaceOnce(html, /<!DOCTYPE html>/i, `<!DOCTYPE html>\n<!-- Generated from index.html by tools/build_language_pages.cjs; edit index.html instead. -->`, 'doctype');
  html = replaceOnce(html, /<html lang="en">/, `<html lang="${lang}" data-page-lang="${lang}">`, '<html lang>');
  html = replaceOnce(html, /<title>[\s\S]*?<\/title>/, `<title>${escapeText(copy.pageTitle)}</title>`, '<title>');
  html = replaceOnce(html, /<meta name="description" content="[^"]*">/, `<meta name="description" content="${escapeAttr(description)}">`, 'description');
  html = replaceOnce(html, /<link rel="canonical" href="[^"]*">/, `<link rel="canonical" href="${url}">`, 'canonical');
  html = replaceOnce(html, /<meta property="og:title" content="[^"]*">/, `<meta property="og:title" content="${escapeAttr(copy.pageTitle)}">`, 'og:title');
  html = replaceOnce(html, /<meta property="og:description" content="[^"]*">/, `<meta property="og:description" content="${escapeAttr(copy.headerSubtitle)}">`, 'og:description');
  html = replaceOnce(html, /<meta property="og:url" content="[^"]*">/, `<meta property="og:url" content="${url}">`, 'og:url');
  html = replaceOnce(html, /<meta property="og:locale" content="[^"]*">/, () => [
    `<meta property="og:locale" content="${locale}">`,
    ...Object.entries(LOCALES).filter(([code]) => code !== lang).map(([, alt]) => `    <meta property="og:locale:alternate" content="${alt}">`),
  ].join('\n'), 'og:locale');
  html = replaceOnce(html, /<meta name="twitter:description" content="[^"]*">/, `<meta name="twitter:description" content="${escapeAttr(copy.headerSubtitle)}">`, 'twitter:description');
  html = replaceOnce(html, /(<script type="application\/ld\+json">)([\s\S]*?)(<\/script>)/, (all, open, json, close) => {
    const data = JSON.parse(json);
    data.url = url;
    data.inLanguage = lang;
    data.description = copy.headerSubtitle;
    return open + JSON.stringify(data).replace(/</g, '\\u003c') + close;
  }, 'JSON-LD');

  return prefill(html, translations[lang]).text;
}

if (require.main === module) {
  const check = process.argv.includes('--check');
  const source = fs.readFileSync(path.join(ROOT, 'index.html'), 'utf8');
  if (/data-page-lang=/.test(source.slice(0, 2000))) throw new Error('index.html must not carry data-page-lang');
  const translations = loadTranslations(source);
  const siteCopy = loadSiteCopy();
  const stale = [];
  for (const lang of Object.keys(PAGES)) {
    const target = path.join(ROOT, PAGES[lang].file);
    const html = build(source, lang, translations, siteCopy);
    const current = fs.existsSync(target) ? fs.readFileSync(target, 'utf8') : null;
    if (current === html) continue;
    stale.push(PAGES[lang].file);
    if (!check) fs.writeFileSync(target, html);
  }
  if (check && stale.length) {
    console.error(`${stale.join(', ')} out of date with index.html. Run node tools/build_language_pages.cjs and commit the result.`);
    process.exit(1);
  }
  console.log(check ? 'Language pages match index.html.' : `Language pages: ${stale.length ? `wrote ${stale.join(', ')}` : 'already up to date'}.`);
}
